<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');check_csrf();$s=db()->prepare('SELECT id FROM students WHERE user_id=?');$s->execute([actor_id()]);$sid=(int)$s->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){try{$result=PaymentService::createDemoPayment($sid,(int)$_POST['fee_id'],(float)$_POST['amount']);$_SESSION['flash']=['success','Payment successful. Receipt '.$result['receipt_no']];}catch(Throwable $e){$_SESSION['flash']=['danger',$e->getMessage()];}redirect('payments.php');}$q=db()->prepare("SELECT sf.id,sf.category,GREATEST(sf.amount-sf.discount-sf.paid_amount,0) pending,sf.due_date FROM student_fees sf WHERE sf.student_id=? AND sf.paid_amount < sf.amount-sf.discount ORDER BY sf.due_date");$q->execute([$sid]);$r=db()->prepare('SELECT p.*,rc.receipt_no FROM payments p LEFT JOIN receipts rc ON rc.payment_id=p.id WHERE p.student_id=? ORDER BY p.id DESC');$r->execute([$sid]);page_top('Digital Payments');flash();?><div class='card p-4 mb-4'><p class='text-muted'>Local XAMPP DemoGateway mode records a payment, updates the fee ledger and creates a receipt atomically.</p><?php foreach($q as $f):?><div class='border rounded p-3 mb-3 d-flex justify-content-between align-items-center'><div><strong><?=e($f['category'])?></strong><div>Pending ₹<?=e(number_format($f['pending'],2))?> · Due <?=e($f['due_date'])?></div></div><form method='post'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input type='hidden' name='fee_id' value='<?=e($f['id'])?>'><input type='hidden' name='amount' value='<?=e($f['pending'])?>'><button class='btn btn-primary'>Pay Now</button></form></div><?php endforeach;?></div><div class='card p-3 table-responsive'><h5>Payment History</h5><table class='table'><tr><th>Reference</th><th>Amount</th><th>Provider</th><th>Status</th><th>Receipt</th><th>Date</th></tr><?php foreach($r as $p):?><tr><td><?=e($p['reference'])?></td><td>₹<?=e(number_format($p['amount'],2))?></td><td><?=e($p['provider'])?></td><td><?=e($p['status'])?></td><td><?=e($p['receipt_no']??'—')?></td><td><?=e($p['paid_at'])?></td></tr><?php endforeach;?></table></div><?php page_bottom();
